<?php
 namespace QQWorld\Framework\View\Test\Unit\Design\Theme; use QQWorld\Framework\View\Design\Theme\Label; use QQWorld\Framework\View\Design\Theme\Label\ListInterface; class LabelTest extends \PHPUnit\Framework\TestCase { protected $model; protected $labelList; protected function setUp() { $this->labelList = $this->getMockBuilder(\QQWorld\Framework\View\Design\Theme\Label\ListInterface::class) ->getMockForAbstractClass(); $this->model = new Label( $this->labelList ); } public function testToOptionArray() { $defaultLabel = (string)new \QQWorld\Framework\Phrase('-- No Theme --'); $data = [ 'value' => '1', 'label' => 'Label1', ]; $this->labelList->expects($this->once()) ->method('getLabels') ->willReturn([$data]); $result = $this->model->toOptionArray(); $this->assertTrue(is_array($result)); $this->assertEquals(2, count($result)); $this->assertEquals($defaultLabel, $result[0]['label']); $this->assertEquals($data['label'], $result[1]['label']); } public function testGetLabelsCollectionForSystemConfiguration() { $defaultLabel = (string)new \QQWorld\Framework\Phrase('-- No Theme --'); $data = [ 'value' => '1', 'label' => 'Label1', ]; $this->labelList->expects($this->once()) ->method('getLabels') ->willReturn([$data]); $result = $this->model->getLabelsCollectionForSystemConfiguration(); $this->assertTrue(is_array($result)); $this->assertEquals(2, count($result)); $this->assertEquals($defaultLabel, $result[0]['label']); $this->assertEquals($data['label'], $result[1]['label']); } } 